examples.template:
ScrollView {
    LazyVStack(alignment: .leading, spacing: MonarchTokens.Space.space2, pinnedViews: [.sectionHeaders]) {
        Text({{intro}}).monarchTextStyle(.body)
        Section {
            ForEach(1...{{rows.count}}, id: \.self) { number in
                Text("{{rows.prefix|raw}} \(number)").monarchTextStyle(.body)
            }
        } header: {
            HStack {
                Text({{header}}).monarchTextStyle(.bodyStrong)
                Spacer(minLength: 0)
                Text({{placeLabel}}).monarchTextStyle(.caption)
            }
            .padding(.vertical, MonarchTokens.Space.space2)
            .background(theme.colors.bgSurface)
        }
    }
    .padding(.horizontal, MonarchTokens.Space.space3)
}
.frame(maxHeight: 260)
.background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous))
.overlay(RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous).strokeBorder(theme.colors.borderSubtle, lineWidth: MonarchTokens.Space.px))

